package tv.vela.launcher;
import android.app.*;import android.content.*;import android.database.*;import android.database.sqlite.*;import android.os.*;import java.io.*;import java.text.*;import java.util.*;

/** Owned emulator only. Public metadata fixtures; no network request or tuner database write. */
public final class XmlTvIntegrationTest extends Instrumentation {
    private void check(boolean value,String message){if(!value)throw new AssertionError(message);}
    private static String stamp(long seconds){SimpleDateFormat d=new SimpleDateFormat("yyyyMMddHHmmss Z",Locale.ROOT);d.setTimeZone(TimeZone.getTimeZone("GMT+02:00"));return d.format(new Date(seconds*1000));}
    private static ByteArrayInputStream xml(String value)throws Exception{return new ByteArrayInputStream(value.getBytes("UTF-8"));}
    public void onCreate(Bundle args){super.onCreate(args);start();}
    public void onStart(){Bundle out=new Bundle();Context c=getTargetContext();File dbFile=new File(c.getCacheDir(),"antenna-epg/test-xmltv.db");try{
        check(Build.FINGERPRINT.contains("generic")||Build.MODEL.contains("sdk"),"Owned emulator only");c.getSharedPreferences("lite_xmltv",0).edit().clear().commit();c.getSharedPreferences("lite_tv",0).edit().putBoolean("online_guide",true).commit();LiteXmlTvGuide guide=new LiteXmlTvGuide(c,"test-xmltv.db");long now=System.currentTimeMillis()/1000;LiveTvData.Channel one=new LiveTvData.Channel(1,"owned","1","La 1 UHD",false,true,false,"dvb1"),two=new LiveTvData.Channel(2,"owned","2","La 2 HD",false,true,false,"dvb2");List<LiveTvData.Channel> tuned=Arrays.asList(one,two);
        String begin="<tv><channel id='La 1 HD'><display-name>La 1.TV</display-name><icon src='https://raw.githubusercontent.com/davidmuma/picons_dobleM/master/icon/La%201.png'/></channel><channel id='Unrelated'><display-name>Unrelated</display-name></channel>";
        String event="<programme channel='La 1 HD' start='"+stamp(now-1800)+"' stop='"+stamp(now+8100)+"'><title>Noticias &amp; ciencia</title><desc>Descripción de prueba.</desc></programme>";
        guide.importGuide(xml(begin+event+"<programme channel='Unrelated' start='"+stamp(now)+"' stop='"+stamp(now+3600)+"'><title>Must not be stored</title></programme></tv>"),tuned,now,new CancellationSignal());
        Map<String,List<LiveTvData.Programme>> read=guide.read(tuned,now,now+10800,new CancellationSignal());check(read.size()==1&&read.get(one.id).get(0).title.equals("Noticias & ciencia"),"Aliases or XML entities failed");check(read.get(one.id).get(0).end==now+8100&&read.get(one.id).get(0).description.equals("Descripción de prueba."),"Timezone or description failed");
        try(SQLiteDatabase db=SQLiteDatabase.openDatabase(dbFile.getPath(),null,SQLiteDatabase.OPEN_READONLY);Cursor rows=db.rawQuery("SELECT COUNT(*) FROM programmes",null)){rows.moveToFirst();check(rows.getInt(0)==1,"Unrelated channels entered cache");}
        check(!guide.refresh(tuned,new CancellationSignal()),"Fresh cache unexpectedly refreshed");LiveTvData.Channel changedId=new LiveTvData.Channel(4096,"owned","24","La 1 HD",false,true,false,"dvb1");check(guide.read(Collections.singletonList(changedId),now,now+3600,new CancellationSignal()).containsKey(changedId.id),"EPG lost match after rescan");
        boolean rejected=false;try{guide.importGuide(xml("<!DOCTYPE tv [<!ENTITY test SYSTEM 'https://example.invalid/entity'>]><tv/>"),tuned,now,new CancellationSignal());}catch(Exception expected){rejected=true;}check(rejected,"DTD was accepted");check(!guide.read(tuned,now,now+3600,new CancellationSignal()).isEmpty(),"Failed import destroyed valid cache");
        rejected=false;try{guide.importGuide(xml(begin+event),tuned,now,new CancellationSignal());}catch(Exception expected){rejected=true;}check(rejected&&!guide.read(tuned,now,now+3600,new CancellationSignal()).isEmpty(),"Truncated XML was committed");
        CancellationSignal cancelled=new CancellationSignal();cancelled.cancel();rejected=false;try{guide.importGuide(xml(begin+event+"</tv>"),tuned,now,cancelled);}catch(Exception expected){rejected=true;}check(rejected,"Import ignored cancellation");
        rejected=false;try(InputStream limited=new LiteXmlTvGuide.Limited(new ByteArrayInputStream(new byte[32]),10,new CancellationSignal())){limited.read(new byte[32]);}catch(IOException expected){rejected=true;}check(rejected,"Byte limit ignored");
        check(LiteXmlTvGuide.timestamp("20261025020000 +0100")-LiteXmlTvGuide.timestamp("20261025020000 +0200")==3600,"DST offset ignored");check(LiteXmlTvGuide.timestamp("20261325020000 +0100")==0,"Invalid date accepted");check(!LiteXmlTvGuide.logoUrl("https://example.invalid/a.png")&&!LiteXmlTvGuide.logoUrl("http://raw.githubusercontent.com/davidmuma/picons_dobleM/a.png"),"Logo whitelist not enforced");
        String ambiguous=begin+"<channel id='Another'><display-name>La 1 HD</display-name></channel>"+event+"</tv>";guide.importGuide(xml(ambiguous),tuned,now,new CancellationSignal());check(guide.read(tuned,now,now+3600,new CancellationSignal()).isEmpty(),"Ambiguous aliases were guessed");c.getSharedPreferences("lite_tv",0).edit().putBoolean("online_guide",false).commit();check(guide.logo(one).isEmpty()&&!guide.refresh(tuned,new CancellationSignal()),"Offline-only setting ignored");
        out.putString("result","PASS streaming XMLTV: only tuned channels stored, entities/descriptions/explicit timezones and DST, programme limits, fresh disk cache, changed antenna URI IDs after rescan, DTD/truncation/cancellation rollback, byte limit, HTTPS logo whitelist, ambiguous aliases refused and offline-only setting. No network request or tuner database write.");
    }catch(Throwable e){out.putString("error",android.util.Log.getStackTraceString(e));}finally{c.getSharedPreferences("lite_tv",0).edit().putBoolean("online_guide",true).commit();dbFile.delete();new File(dbFile.getPath()+"-journal").delete();}finish(out.containsKey("error")?1:-1,out);}
}
